const frame = msg.payload || msg;
let canId = frame.canid & 0x1FFFFFFF;
const data = frame.data || [];

let state = flow.get("pcsAlgoParamsState") || {
    kind: "PcsAlgoParamsState",
    version: 1,
    // PCS_ALGO_PARAMS_1 (0x66B973x)
    pcs_modOvertProtC: null,
    pcs_ccCvRechgV: null,
    pcs_batCvChgV: null,
    pcs_cvChgMaxTimeMin: null,
    // PCS_ALGO_PARAMS_2 (0x66B974x)
    pcs_cvToFloatI: null,
    pcs_floatChgV: null,
    pcs_floatToCcI: null
};

// Helper function
function s16(buf, offset) {
    let val = (buf[offset] & 0xFF) | ((buf[offset + 1] & 0xFF) << 8);
    return val > 32767 ? val - 65536 : val;
}

var processed = false;

// ==================== PCS_ALGO_PARAMS_1 (0x66B973x) ====================
if ((canId & 0xFFFFFFF0) === 0x66B9730) {
    processed = true;
    // Bit 0-15: Module Over Temperature Protection (16 bit, Signed, Factor: 0.1, Unit: °C)
    // Min: 0, Max: 200
    state.pcs_modOvertProtC = s16(data, 0) * 0.1;

    // Bit 16-31: CC/CV Recharge Voltage (16 bit, Signed, Factor: 0.1, Unit: V)
    // Min: 0, Max: 1500
    state.pcs_ccCvRechgV = s16(data, 2) * 0.1;

    // Bit 32-47: Battery CV Charge Voltage (16 bit, Signed, Factor: 0.1, Unit: V)
    // Min: 0, Max: 1500
    state.pcs_batCvChgV = s16(data, 4) * 0.1;

    // Bit 48-63: CV Charge Max Time (16 bit, Signed, Factor: 1, Unit: min)
    // Min: 0, Max: 65535
    state.pcs_cvChgMaxTimeMin = s16(data, 6);
}

// ==================== PCS_ALGO_PARAMS_2 (0x66B974x) ====================
if ((canId & 0xFFFFFFF0) === 0x66B9740) {
    processed = true;
    // Bit 0-15: CV to Float Current (16 bit, Signed, Factor: 0.1, Unit: A)
    // Min: 0, Max: 5000
    state.pcs_cvToFloatI = s16(data, 0) * 0.1;

    // Bit 16-31: Float Charge Voltage (16 bit, Signed, Factor: 0.1, Unit: V)
    // Min: 0, Max: 1500
    state.pcs_floatChgV = s16(data, 2) * 0.1;

    // Bit 32-47: Float to CC Current (16 bit, Signed, Factor: 0.1, Unit: A)
    // Min: 0, Max: 5000
    state.pcs_floatToCcI = s16(data, 4) * 0.1;
}

if (!processed) {
    return null;
}

state.timestampUtc = new Date().toISOString();
flow.set("pcsAlgoParamsState", state);
msg.payload = state;
return msg;

var state = flow.get("pcsAlgoParamsState");
if (state) {
    msg.payload = state;
    return msg;
}
msg.payload = { error: "No data yet" };
return msg;
